Here's the code for the different parts of a basic chat application:

**Server.java:**
```java
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashSet;
import java.util.Set;

public class Server {
    private int port;
    private Set<MessageHandler> userHandlers = new HashSet<>();

    public Server(int port) {
        this.port = port;
    }

    public void startServer() {
        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("Chat server started on port: " + port);

            while (true) {
                Socket socket = serverSocket.accept();
                System.out.println("New user connected");
                MessageHandler newUser = new MessageHandler(socket, this);
                userHandlers.add(newUser);
                newUser.start();
            }

        } catch (IOException e) {
            System.out.println("Error starting server: " + e.getMessage());
        }
    }

    public void broadcast(String message, MessageHandler sender) {
        for (MessageHandler handler : userHandlers) {
            if (handler != sender) {
                handler.sendMessage(message);
            }
        }
    }

    public void removeUser(MessageHandler handler) {
        userHandlers.remove(handler);
    }

    public static void main(String[] args) {
        int port = 12345;
        Server server = new Server(port);
        server.startServer();
    }
}
```

