mass_max = 200; % Max mass to consider (kg)
mass_step = 0.1; % Mass increment (kg)
mass_range = mass_min:mass_step:mass_max;

% Calculate velocities for mass range
velocities = zeros(1, length(mass_range));
for i = 1:length(mass_range)
    mass = mass_range(i);
    % Calculate terminal velocity for current mass
    terminal_velocity = sqrt((2 * mass * g) / c);
    % Velocity after target time (analytical solution for faster computation)
    velocities(i) = terminal_velocity * tanh((g / terminal_velocity) * target_time);
end

% Plot the velocities against mass
figure;
plot(mass_range, velocities);
xlabel('Mass (kg)');
ylabel('Velocity after 3s (m/s)');
title('Jumper Velocity vs. Mass');

