const bleno = require('bleno');

const DEVICE_NAME = 'Ubuntu-BLE-Device';
const DATA_EXCHANGE_SERVICE_UUID = 'fffffffffffffffffffffffffffffff0';
const DATA_CHARACTERISTIC_UUID = 'fffffffffffffffffffffffffffffff1';

class DataExchangeCharacteristic extends bleno.Characteristic {
  constructor() {
    super({
      uuid: DATA_CHARACTERISTIC_UUID,
      properties: ['read', 'write', 'notify'],
      value: null,
    });

    this.data = Buffer.from('Hello, BLE!');
    this._updateValueCallback = null;
  }

  onReadRequest(offset, callback) {
    console.log('Data read request');
    callback(bleno.Characteristic.RESULT_SUCCESS, this.data);
  }

  onWriteRequest(data, offset, withoutResponse, callback) {
    console.log('Data write request:', data.toString());
    this.data = data;
    if (this._updateValueCallback) {
      this._updateValueCallback(data);
    }
    callback(bleno.Characteristic.RESULT_SUCCESS);
  }

  onSubscribe(maxValueSize, updateValueCallback) {
    console.log('Data notification subscribe');
    this._updateValueCallback = updateValueCallback;
  }

  onUnsubscribe() {
    console.log('Data notification unsubscribe');
    this._updateValueCallback = null;
  }
}

bleno.on('stateChange', (state) => {
  console.log('State change:', state);
  if (state === 'poweredOn') {
    bleno.startAdvertising(DEVICE_NAME, [DATA_EXCHANGE_SERVICE_UUID]);
  } else {
    bleno.stopAdvertising();
  }
});

bleno.on('advertisingStart', (error) => {
  if (!error) {
    console.log('Advertising started');
    const dataExchangeService = new bleno.PrimaryService({
      uuid: DATA_EXCHANGE_SERVICE_UUID,
      characteristics: [new DataExchangeCharacteristic()],
    });

    bleno.setServices([dataExchangeService], (error) => {
      if (error) {
        console.log('Error setting services:', error);
      } else {
        console.log('Services set successfully');
      }
    });
  } else {
    console.log('Error starting advertising:', error);
  }
});
```

