```java
import java.math.*;

public class DistanceCalculator {

    public static void main(String[] args) {
        // get the coordinates of the two cities
        double lat1 = 38.5596; // Istanbul's latitude
        double lon1 = 25.0483; // Istanbul's longitude

        double lat2 = 40.7127; // New York City's latitude
        double lon2 = -74.0060; // New York City's longitude

        // calculate the distance
        double distance = distanceBetweenCities(lat1, lon1, lat2, lon2);

        // print the result
        System.out.println("The distance between Istanbul and New York City is " + distance + " km.");
    }

    static public double distanceBetweenCities(double lat1, double lon1, double lat2, double lon2) {
        // convert the latitude and longitude from degrees to radians
        lat1 = Math.toRadians(lat1);
        lon1 = Math.toRadians(lon1);
        lat2 = Math.toRadians(lat2);
        lon2 = Math.toRadians(lon2);

        // use the Haversine formula to calculate the distance
        double earthCircumference = 6371.01; // Earth's circumference in km
        double deltaLat = Math.abs(lat2 - lat1);
        double deltaLon = Math.abs(lon2 - lon1);
        double a = Math.sin(deltaLat / 2) * Math.sin(deltaLat / 2) +
                   Math.sin(deltaLon / 2) * Math.sin(deltaLon / 2) *
                   Math.cos(lat1 / 2) * Math.cos(lat2 / 2);
        // double a = Math.sin(lat1-lat2/2)се♭*Math.cos(lon2-lon1/2)*
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        double distance = earthCircumference * c;

        return distance;
    }
}
```

